import sys

def lcs_length(a: str, b: str) -> int:
    if len(a) > len(b):
        a, b = b, a
    if not a:
        return 0
    # Bit-parallel LCS (Allison-Dix / Crochemore et al.)
    masks = {}
    for i, ch in enumerate(a):
        masks[ch] = masks.get(ch, 0) | (1 << i)

    S = (1 << len(a)) - 1
    for ch in b:
        pm = masks.get(ch, 0)
        u = S & pm
        S = (S + u) | (S - u)

    return len(a) - (S & ((1 << len(a)) - 1)).bit_count()

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        a = lines[0] if lines else ""
        b = ""
    else:
        a, b = lines[0], lines[1]
    print(lcs_length(a, b))

if __name__ == "__main__":
    main()
